// FindConvolutionBackwardDataAlgorithm Search and run the backwards data convolution algorithms and return a list of kernel times.
//
// This function attempts all MIOpen backward data convolution algorithms, and outputs the
// performance metrics to a user-allocated array of type [ConvAlgoPerf].
// These metrics are written in sorted fashion where the first element has the lowest compute time.
// This function is mandatory before using backwards convolutions. Users can chose the top-most
// algorithm if they only care about the fastest algorithm.
//
// This function is mandatory before using [Handle.ConvolutionBackwardData]. In order to
// execute this function, ConvolutionBackwardsDataGetWorkSpaceSize() must be run to determine
// the required memory for this search.
//
// * If exhaustiveSearch == 0, MIOpen will look for the first kernel with a configuration match. If
// a configuration match is not found, a default configuration will be returned.
//
// * If exhaustiveSearch == 1, MIOpen will look for the best kernel for the provided configuration.
// If a match is not found, an exhaustive search is performed by running individual algorithms.
//
// If using Group/Depthwise convolution mode, call [ConvolutionDescriptor.SetConvolutionGroupCount] before running
// this.
//
//   - dyDesc: Tensor descriptor for data input tensor dy (input)
//   - dy: Data delta tensor dy (input)
//   - wDesc: Tensor descriptor for weight tensor w (input)
//   - w: Weights tensor w (input)
//   - convDesc: Convolution layer descriptor (input)
//   - dxDesc: Tensor descriptor for output data tensor dx (input)
//   - dx: Data delta tensor dx (input)
//   - requestAlgoCount: Number of algorithms to return kernel times (input)
//   - returnedAlgoCount: Pointer to number of algorithms returned (output)
//   - perfResults: Pointer to union of best algorithm for forward and backwards (output)
//   - workSpace: Pointer to workspace buffer (input)
//   - workSpaceSize: Size in bytes of the workspace buffer (input). The buffer must be allocated on the device by the caller. The size of the buffer should be determined by calling [Handle.ConvolutionBackwardDataGetWorkSpaceSize], see its documentation for details
//   - exhaustiveSearch: A boolean to toggle a full search of all algorithms and configurations (input)
//
// Wraps miopenFindConvolutionBackwardDataAlgorithm.
func (h Handle) FindConvolutionBackwardDataAlgorithm(dyDesc TensorDescriptor, dy uintptr, wDesc TensorDescriptor, w uintptr, convDesc ConvolutionDescriptor, dxDesc TensorDescriptor, dx uintptr, requestAlgoCount int32, returnedAlgoCount *int32, perfResults *ConvAlgoPerf, workSpace uintptr, workSpaceSize uint, exhaustiveSearch bool) error {
	return FindConvolutionBackwardDataAlgorithm(h, dyDesc, dy, wDesc, w, convDesc, dxDesc, dx, requestAlgoCount, returnedAlgoCount, perfResults, workSpace, workSpaceSize, exhaustiveSearch)
}

// FindConvolutionBackwardWeightsAlgorithm Search and run the backwards weights convolutional algorithms and return a list of kernel times.
//
// This function attempts all MIOpen backward weights convolution algorithms, and outputs
// the performance metrics to a user-allocated array of type [ConvAlgoPerf]. These metrics are
// written in sorted fashion where the first element has the lowest compute time.
// This function is mandatory before using backwards weight convolutions. Users can chose the
// top-most algorithm if they only care about the fastest algorithm.
//
// This function is mandatory before using [Handle.ConvolutionBackwardWeights]. In order to
// execute this function, ConvolutionBackwardsWeightsGetWorkSpaceSize() must be run to
// determine the required memory for this search.
//
// * If exhaustiveSearch == 0, MIOpen will look for the first kernel with a configuration match. If
// a configuration match is not found, a default configuration will be returned.
//
// * If exhaustiveSearch == 1, MIOpen will look for the best kernel for the provided configuration.
// If a match is not found, an exhaustive search is performed by running individual algorithms.
//
// If using Group/Depthwise convolution mode, call [ConvolutionDescriptor.SetConvolutionGroupCount] before running
// this.
//
//   - dyDesc: Tensor descriptor for data input tensor dy (input)
//   - dy: Data delta tensor dy (input)
//   - xDesc: Tensor descriptor for output data tensor x (input)
//   - x: Data delta tensor dx (input)
//   - convDesc: Convolution layer descriptor (input)
//   - dwDesc: Tensor descriptor for weight tensor dw (input)
//   - dw: Weights delta tensor dw (input)
//   - requestAlgoCount: Number of algorithms to return kernel times (input)
//   - returnedAlgoCount: Pointer to number of algorithms returned (output)
//   - perfResults: Pointer to union of best algorithm for forward and backwards (output)
//   - workSpace: Pointer to workspace buffer (input)
//   - workSpaceSize: Size in bytes of the workspace buffer (input). The buffer must be allocated on the device by the caller. The size of the buffer should be determined by calling [Handle.ConvolutionBackwardWeightsGetWorkSpaceSize], see its documentation for details
//   - exhaustiveSearch: A boolean to toggle a full search of all algorithms and configurations (input)
//
// Wraps miopenFindConvolutionBackwardWeightsAlgorithm.
func (h Handle) FindConvolutionBackwardWeightsAlgorithm(dyDesc TensorDescriptor, dy uintptr, xDesc TensorDescriptor, x uintptr, convDesc ConvolutionDescriptor, dwDesc TensorDescriptor, dw uintptr, requestAlgoCount int32, returnedAlgoCount *int32, perfResults *ConvAlgoPerf, workSpace uintptr, workSpaceSize uint, exhaustiveSearch bool) error {
	return FindConvolutionBackwardWeightsAlgorithm(h, dyDesc, dy, xDesc, x, convDesc, dwDesc, dw, requestAlgoCount, returnedAlgoCount, perfResults, workSpace, workSpaceSize, exhaustiveSearch)
}

// FindConvolutionForwardAlgorithm Search and run the forward convolutional algorithms and return a list of kernel times.
//
// This function attempts all MIOpen forward convolution algorithms based on
// the input configuration, and outputs performance metrics to a
// user-allocated array of type [ConvAlgoPerf]. These metrics are written
// in a sorted fashion where the first element has the lowest compute time.
// Users can chose the top-most algorithm if they only care about the fastest
