// FusedAdam Perform Fused Adam optimization for a single tensor (Adaptive Moment Estimation).
//
// This function implements the Fused Adam optimization algorithm. Adam, short for Adaptive Moment
// Estimation, extends the RMSProp optimizer. It combines the advantages of AdaGrad and RMSProp by
// adaptively adjusting learning rates for each parameter using the first and second moments of
// gradients. Fused Adam optimization efficiently combines multiple operations into a single kernel,
// reducing memory access overhead and improving performance.
//
// Additionally, Fused Adam can be utilized in both adam w and Automatic Mixed Precision (AMP),
// enabling accelerated model training and reduced memory consumption. AMP supports FP16
// computation, optimizing model calculations using a mixture of FP32 and FP16 precision to enhance
// training speed. When utilizing AMP, FoundInf, ScaleGrad, and step tensors should be employed. In
// AMP mode, the execution of Adam is determined based on the FoundInf value. State Step accepts
// both int values and int tensors. If a Step tensor is employed, the step received as an int is
// disregarded, and if Adam is executed, the step tensor is incremented by 1.
//
// @code
// // Execute Adam
// [Handle.FusedAdam](handle,
// paramDesc,
// param,
// gradDesc,
// grad,
// expAvgDesc,
// expAvg,
// expAvgSqDesc,
// expAvgSq,
// NULL, // Unused maxExpAvgSqDesc because amsgrad is false
// NULL,
// NULL, // Unused stateStep Tensor because use step integer argument
// NULL,
// step,
// lr,
// beta1,
// beta2,
// weight_decay,
// eps,
// false, // amsgrad
// false, // maximize
// false, // adamw
// NULL, // Unused gradScale Tensor because not amp
// NULL,
// NULL, // Unused foundInf Tensor because not amp
// NULL);
//
// // Execute AdamW
// [Handle.FusedAdam](handle,
// paramDesc,
// param,
// gradDesc,
// grad,
// expAvgDesc,
// expAvg,
// expAvgSqDesc,
// expAvgSq,
// NULL, // Unused maxExpAvgSqDesc because amsgrad is false
// NULL,
// NULL, // Unused stateStep Tensor because use step integer argument
// NULL,
// step,
// lr,
// beta1,
// beta2,
// weight_decay,
// eps,
// false, // amsgrad
// false, // maximize
// true, // adamw
// NULL, // Unused gradScale Tensor because not amp
// NULL,
// NULL, // Unused foundInf Tensor because not amp
// NULL);
//
// // Execute AMP Adam
// [Handle.FusedAdam](handle,
// paramDesc,
// param,
// gradDesc,
// grad,
// expAvgDesc,
// expAvg,
// expAvgSqDesc,
// expAvgSq,
// NULL, // Unused maxExpAvgSqDesc because amsgrad is false
// NULL,
// stateStepDesc,
// stateStep,
// -1, // Ignore step value because stateStep Tensor is used
// lr,
// beta1,
// beta2,
// weight_decay,
// eps,
// false, // amsgrad
// false, // maximize
// false, // adamw
// gradScaleDesc,
// gradScale,
// foundInfDesc,
// foundInf);
// @endcode
//
//   - paramDesc: Tensor descriptor for the input parameter tensor (input)
//   - param: Input parameter tensor (input)
//   - gradDesc: Tensor descriptor for the input gradient tensor (input)
//   - grad: Input gradient tensor (input)
//   - expAvgDesc: Tensor descriptor for the input exponential moving average tensor (input)
//   - expAvg: Input exponential moving average tensor (input)
//   - expAvgSqDesc: Tensor descriptor for the input exponential moving average squared tensor (input)
//   - expAvgSq: Input exponential moving average squared tensor (input)
//   - maxExpAvgSqDesc: Tensor descriptor for the input maximum exponential moving average squared tensor. Used when amsgrad is true (input, optional)
//   - maxExpAvgSq: Input maximum exponential moving average squared tensor. Used when amsgrad is true (input, optional)
//   - stateStepDesc: Tensor descriptor for the input state step tensor (input)
//   - stateStep: Input state step tensor (input)
//   - stateStep: Input state step. used when the step tensor is null (input)
//   - lr: Learning rate (input)
//   - beta1: Coefficient used for computing the first moment running average of gradient (input)
//   - beta2: Coefficient used for computing the second moment running average of gradient (input)
//   - weightDecay: Weight decay (input)
//   - eps: Term added to the denominator to improve numerical stability (input)
//   - amsgrad: Flag indicating whether to use the AMSGrad variant of Adam (input)
//   - maximize: Flag indicating whether to maximize the objective with respect to the parameters (input)
//   - adamw: If true, the operation becomes AdamW (input)
//   - gradScaleDesc: Tensor descriptor for the input grad scale tensor (input, optional)
//   - gradScale: Input grad scale tensor (input, optional)
//   - foundInfDesc: Tensor descriptor for the input found inf tensor (input, optional)
//   - foundInf: Tensor indicating the presence of inf or NaN in gradients. If true, skips operation and step update (input, optional)
//
// Wraps miopenFusedAdam.
func (h Handle) FusedAdam(paramDesc TensorDescriptor, param uintptr, gradDesc TensorDescriptor, grad uintptr, expAvgDesc TensorDescriptor, expAvg uintptr, expAvgSqDesc TensorDescriptor, expAvgSq uintptr, maxExpAvgSqDesc TensorDescriptor, maxExpAvgSq uintptr, stateStepDesc TensorDescriptor, stateStep uintptr, stateStep2 uint32, lr float32, beta1 float32, beta2 float32, weightDecay float32, eps float32, amsgrad bool, maximize bool, adamw bool, gradScaleDesc TensorDescriptor, gradScale uintptr, foundInfDesc TensorDescriptor, foundInf uintptr) error {
	return FusedAdam(h, paramDesc, param, gradDesc, grad, expAvgDesc, expAvg, expAvgSqDesc, expAvgSq, maxExpAvgSqDesc, maxExpAvgSq, stateStepDesc, stateStep, stateStep2, lr, beta1, beta2, weightDecay, eps, amsgrad, maximize, adamw, gradScaleDesc, gradScale, foundInfDesc, foundInf)
}

// FusedAdamWithOutput Execute single tensor Adam optimization and receive the result in a separate output tensor.
//
// This function is equivalent to [Handle.FusedAdam] but receives the result in a separate output
// tensor.
// [Handle.[Handle.FusedAdam]]
//
// @code
// // Execute Adam
// [Handle.FusedAdamWithOutput](handle,
// paramInDesc,
// paramIn,
// paramOutDesc,
// paramOut,
// NULL, // Unused paramOutFloat16 tensor because is not amp
// NULL,
// gradInDesc,
// gradIn,
// expAvgInDesc,
// expAvgIn,
// expAvgOutDesc,
// expAvgOut,
// expAvgInSqDesc,
// expAvgSqIn,
// expAvgSqOutDesc,
// expAvgSqOut,
// NULL, // Unused maxExpAvgSqIn tensor because amsgrad is false
// NULL,
// NULL, // Unused maxExpAvgSqOut tensor because amsgrad is false
// NULL,
// NULL, // Unused stateStepIn tensor because use step integer argument
// NULL,
// NULL, // Unused stateStepOut tensor because use step integer argument
// NULL,
// step,
// lr,
// beta1,
// beta2,
// weight_decay,
// eps,
// false, // amsgrad
// false, // maximize
// false, // adamw
// NULL, // Unused gradScale Tensor because not amp
// NULL,
// NULL, // Unused foundInf Tensor because not amp
// NULL);
//
// // Execute Amp Adam
// [Handle.FusedAdamWithOutput](handle,
// paramInDesc,
// paramIn,
// paramOutDesc,
// paramOut,
// paramOutFloat16Desc, // paramOutFloat16 tensor is optional in amp
// paramOutFloat16,
// gradInDesc,
// gradIn,
// expAvgInDesc,
// expAvgIn,
// expAvgOutDesc,
// expAvgOut,
// expAvgInSqDesc,
// expAvgSqIn,
// expAvgSqIn,
// expAvgSqOutDesc,
// expAvgSqOut,
// NULL, // Unused maxExpAvgSqIn tensor because amsgrad is false
// NULL,
// NULL, // Unused maxExpAvgSqOut tensor because amsgrad is false
// NULL,
// stateStepInDesc,
// stateStepIn,
// stateStepOutDesc,
// stateStepOut
// -1, // Ignore step value because stateStep Tensor is used
// lr, beta1, beta2, weight_decay, eps,
// false, // amsgrad
// false, // maximize
// false, // adamw
// gradScaleDesc,
// gradScale,
// foundInfDesc,
// foundInf);
// @endcode
//
//   - paramInDesc: Tensor descriptor for the input parameter tensor (input)
//   - paramIn: Input parameter tensor (input)
//   - paramOutDesc: Tensor descriptor for the output parameter tensor (input)
//   - paramOut: Output parameter tensor (output)
//   - paramOutFloat16Desc: Tensor descriptor for the output parameter tensor float16 (input, optional)
//   - paramOutFloat16: Output parameter tensor (output, optional)
//   - gradInDesc: Tensor descriptor for the input gradient tensor (input)
//   - gradIn: Input gradient tensor (input)
//   - expAvgInDesc: Tensor descriptor for the input exponential moving average tensor (input)
//   - expAvgIn: Input exponential moving average tensor (input)
//   - expAvgOutDesc: Tensor descriptor for the output exponential moving average tensor (input)
//   - expAvgOut: Output exponential moving average tensor (output)
//   - expAvgSqInDesc: Tensor descriptor for the input exponential moving average squared tensor (input)
//   - expAvgSqIn: Input exponential moving average squared tensor (input)
//   - expAvgSqOutDesc: Tensor descriptor for the output exponential moving average squared tensor (input)
//   - expAvgSqOut: Output exponential moving average squared tensor (output)
//   - maxExpAvgSqInDesc: Tensor descriptor for the input maximum exponential moving average squared tensor. Used when amsgrad is true (input, optional)
//   - maxExpAvgSqIn: Input maximum exponential moving average squared tensor. Used when amsgrad is true (input, optional)
//   - maxExpAvgSqOutDesc: Tensor descriptor for the output maximum exponential moving average squared tensor. Used when amsgrad is true (input, optional)
//   - maxExpAvgSqOut: Output maximum exponential moving average squared tensor. Used when amsgrad is true (output, optional)
//   - stateStepInDesc: Tensor descriptor for the input state step tensor (input, optional)
//   - stateStepIn: Input state step tensor (input, optional)
//   - stateStepOutDesc: Tensor descriptor for the output state step tensor (input, optional)
//   - stateStepOut: Output state step tensor that stores the updated step value. (output, optional)
//   - stateStep: Input state step, It is used when the step tensor is null. (input)
//   - lr: Learning rate (input)
//   - beta1: Coefficient used for computing the first moment running average of gradient (input)
//   - beta2: Coefficient used for computing the second moment running average of gradient (input)
//   - weightDecay: Weight decay (input)
//   - eps: Term added to the denominator to improve numerical stability (input)
//   - amsgrad: Flag indicating whether to use the AMSGrad variant of Adam (input)
//   - maximize: Flag indicating whether to maximize the objective with respect to the parameters (input)
//   - adamw: If it is true, the operation becomes AdamW (input)
//   - gradScaleDesc: Tensor descriptor for the input grad scale tensor (input, optional)
//   - gradScale: Input grad scale tensor (input, optional)
//   - foundInfDesc: Tensor descriptor for the input found inf tensor (input, optional)
//   - foundInf: Tensor indicating presence of inf or nan in gradients. If true, skips operation and step update. (input, optional)
//
// Wraps miopenFusedAdamWithOutput.
func (h Handle) FusedAdamWithOutput(paramInDesc TensorDescriptor, paramIn uintptr, paramOutDesc TensorDescriptor, paramOut uintptr, paramOutFloat16Desc TensorDescriptor, paramOutFloat16 uintptr, gradInDesc TensorDescriptor, gradIn uintptr, expAvgInDesc TensorDescriptor, expAvgIn uintptr, expAvgOutDesc TensorDescriptor, expAvgOut uintptr, expAvgSqInDesc TensorDescriptor, expAvgSqIn uintptr, expAvgSqOutDesc TensorDescriptor, expAvgSqOut uintptr, maxExpAvgSqInDesc TensorDescriptor, maxExpAvgSqIn uintptr, maxExpAvgSqOutDesc TensorDescriptor, maxExpAvgSqOut uintptr, stateStepInDesc TensorDescriptor, stateStepIn uintptr, stateStepOutDesc TensorDescriptor, stateStepOut uintptr, stateStep uint32, lr float32, beta1 float32, beta2 float32, weightDecay float32, eps float32, amsgrad bool, maximize bool, adamw bool, gradScaleDesc TensorDescriptor, gradScale uintptr, foundInfDesc TensorDescriptor, foundInf uintptr) error {
	return FusedAdamWithOutput(h, paramInDesc, paramIn, paramOutDesc, paramOut, paramOutFloat16Desc, paramOutFloat16, gradInDesc, gradIn, expAvgInDesc, expAvgIn, expAvgOutDesc, expAvgOut, expAvgSqInDesc, expAvgSqIn, expAvgSqOutDesc, expAvgSqOut, maxExpAvgSqInDesc, maxExpAvgSqIn, maxExpAvgSqOutDesc, maxExpAvgSqOut, stateStepInDesc, stateStepIn, stateStepOutDesc, stateStepOut, stateStep, lr, beta1, beta2, weightDecay, eps, amsgrad, maximize, adamw, gradScaleDesc, gradScale, foundInfDesc, foundInf)
}

