//   - yDesc: Destination Tensor descriptor for tensor y (input)
//   - y: Destination Tensor y (output)
//
// Wraps miopenTransformTensor.
func (h Handle) TransformTensor(alpha uintptr, xDesc TensorDescriptor, x uintptr, beta uintptr, yDesc TensorDescriptor, y uintptr) error {
	return TransformTensor(h, alpha, xDesc, x, beta, yDesc, y)
}

// TransformersAdamW Implements Adam algorithm with weight decay fix as introduced in Decoupled Weight Decay...
//
// [Handle.[Handle.FusedAdam]]
//
// @code
// // Execute Adam
// [Handle.TransformersAdamW](handle,
// paramDesc,
// param,
// gradDesc,
// grad,
// expAvgDesc,
// expAvg,
// expAvgSqDesc,
// expAvgSq,
// NULL, // Unused stateStep Tensor because use step integer argument
// NULL,
// step,
// lr,
// beta1,
// beta2,
// weight_decay,
// eps,
// true, // correct_bias
// NULL, // Unused gradScale Tensor because not amp
// NULL,
// NULL, // Unused foundInf Tensor because not amp
// NULL);
//
// // Execute AMP Adam
// [Handle.TransformersAdamW](handle,
// paramDesc,
// param,
// gradDesc,
// grad,
// expAvgDesc,
// expAvg,
// expAvgSqDesc,
// expAvgSq,
// stateStepDesc,
// stateStep,
// -1, // Ignore step value because stateStep Tensor is used
// lr,
// beta1,
// beta2,
// weight_decay,
// eps,
// true, // correct_bias
// gradScaleDesc,
// gradScale,
// foundInfDesc,
// foundInf);
// @endcode
//
//   - paramDesc: Tensor descriptor for the input parameter tensor (input)
//   - param: Input parameter tensor (input)
//   - gradDesc: Tensor descriptor for the input gradient tensor (input)
//   - grad: Input gradient tensor (input)
//   - expAvgDesc: Tensor descriptor for the input exponential moving average tensor (input)
//   - expAvg: Input exponential moving average tensor (input)
//   - expAvgSqDesc: Tensor descriptor for the input exponential moving average squared tensor (input)
//   - expAvgSq: Input exponential moving average squared tensor (input)
//   - stateStepDesc: Tensor descriptor for the input state step tensor (input)
//   - stateStep: Input state step tensor (input)
//   - stateStep: Input state step. used when the step tensor is null (input)
//   - lr: Learning rate (input)
//   - beta1: Coefficient used for computing the first moment running average of gradient (input)
//   - beta2: Coefficient used for computing the second moment running average of gradient (input)
//   - weightDecay: Weight decay (input)
//   - eps: Term added to the denominator to improve numerical stability (input)
//   - correctBias: Whether or not to correct bias in Adam (for instance, in Bert TF repository they use False)
//   - gradScaleDesc: Tensor descriptor for the input grad scale tensor (input, optional)
//   - gradScale: Input grad scale tensor (input, optional)
//   - foundInfDesc: Tensor descriptor for the input found inf tensor (input, optional)
//   - foundInf: Tensor indicating the presence of inf or NaN in gradients. If true, skips operation and step update (input, optional)
//
// Wraps miopenTransformersAdamW.
func (h Handle) TransformersAdamW(paramDesc TensorDescriptor, param uintptr, gradDesc TensorDescriptor, grad uintptr, expAvgDesc TensorDescriptor, expAvg uintptr, expAvgSqDesc TensorDescriptor, expAvgSq uintptr, stateStepDesc TensorDescriptor, stateStep uintptr, stateStep2 uint32, lr float32, beta1 float32, beta2 float32, weightDecay float32, eps float32, correctBias bool, gradScaleDesc TensorDescriptor, gradScale uintptr, foundInfDesc TensorDescriptor, foundInf uintptr) error {
	return TransformersAdamW(h, paramDesc, param, gradDesc, grad, expAvgDesc, expAvg, expAvgSqDesc, expAvgSq, stateStepDesc, stateStep, stateStep2, lr, beta1, beta2, weightDecay, eps, correctBias, gradScaleDesc, gradScale, foundInfDesc, foundInf)
}

// TransformersAdamWWithOutput Execute single tensor Adam optimization and receive the result in a separate output tensor.
//
// This function is equivalent to TransformersAdam but receives the result in a separate
// output tensor.
// [Handle.[Handle.TransformersAdamW]]
// [Handle.[Handle.FusedAdamWithOutput]]
//
// @code
// // Execute Adam
// [Handle.TransformersAdamWWithOutput](handle,
// paramInDesc,
// paramIn,
// paramOutDesc,
// paramOut,
// NULL, // Unused paramOutFloat16 tensor because is not amp
// NULL,
// gradInDesc,
// gradIn,
// expAvgInDesc,
// expAvgIn,
// expAvgOutDesc,
// expAvgOut,
// expAvgInSqDesc,
// expAvgSqIn,
// expAvgSqOutDesc,
// expAvgSqOut,
// NULL, // Unused stateStepIn tensor because use step int
// NULL,
// NULL, // Unused stateStepOut tensor because use step int
// NULL,
// step,
// lr,
// beta1,
// beta2,
// weight_decay,
// eps,
// -1, // step_size
// true, // correct_bias
// NULL, // Unused gradScale Tensor because not amp
// NULL,
// NULL, // Unused foundInf Tensor because not amp
// NULL);
//
// // Execute Amp Adam
// [Handle.TransformersAdamWWithOutput](handle,
// paramInDesc,
// paramIn,
// paramOutDesc,
// paramOut,
// paramOutFloat16Desc, // optional in amp
// paramOutFloat16,
// gradInDesc,
// gradIn,
// expAvgInDesc,
// expAvgIn,
// expAvgOutDesc,
// expAvgOut,
// expAvgInSqDesc,
// expAvgSqIn,
// expAvgSqIn,
// expAvgSqOutDesc,
// expAvgSqOut,
// stateStepInDesc,
// stateStepIn,
// stateStepOutDesc,
// stateStepOut
// -1, // Ignore step value because stateStep Tensor is used
// lr,
// beta1,
// beta2,
// weight_decay,
// eps,
// -1, // step_size
// true, // correct_bias
// NULL, // Unused gradScale Tensor because not amp
// NULL,
// NULL, // Unused foundInf Tensor because not amp
// NULL);
// @endcode
//
//   - paramInDesc: Tensor descriptor for the input parameter tensor (input)
//   - paramIn: Input parameter tensor (input)
//   - paramOutDesc: Tensor descriptor for the output parameter tensor (input)
//   - paramOut: Output parameter tensor (output)
//   - paramOutFloat16Desc: Tensor descriptor for the output parameter tensor float16 (input, optional)
//   - paramOutFloat16: Output parameter tensor (output, optional)
//   - gradInDesc: Tensor descriptor for the input gradient tensor (input)
//   - gradIn: Input gradient tensor (input)
//   - expAvgInDesc: Tensor descriptor for the input exponential moving average tensor (input)
//   - expAvgIn: Input exponential moving average tensor (input)
//   - expAvgOutDesc: Tensor descriptor for the output exponential moving average tensor (input)
//   - expAvgOut: Output exponential moving average tensor (output)
//   - expAvgSqInDesc: Tensor descriptor for the input exponential moving average squared tensor (input)
//   - expAvgSqIn: Input exponential moving average squared tensor (input)
//   - expAvgSqOutDesc: Tensor descriptor for the output exponential moving average squared tensor (input)
//   - expAvgSqOut: Output exponential moving average squared tensor (output)
//   - stateStepInDesc: Tensor descriptor for the input state step tensor (input, optional)
//   - stateStepIn: Input state step tensor (input, optional)
//   - stateStepOutDesc: Tensor descriptor for the output state step tensor (input, optional)
//   - stateStepOut: Output state step tensor that stores the updated step value. (output, optional)
//   - stateStep: Input state step, It is used when the step tensor is null. (input)
//   - lr: Learning rate (input)
//   - beta1: Coefficient used for computing the first moment running average of gradient (input)
//   - beta2: Coefficient used for computing the second moment running average of gradient (input)
//   - weightDecay: Weight decay (input)
//   - eps: Term added to the denominator to improve numerical stability (input)
//   - stepSize: Pre-calculated step_size, used for performance enhancement (input)
//   - correctBias: Whether or not to correct bias in Adam (for instance, in Bert TF repository they use False) (input)
//   - gradScaleDesc: Tensor descriptor for the input grad scale tensor (input, optional)
//   - gradScale: Input grad scale tensor (input, optional)
//   - foundInfDesc: Tensor descriptor for the input found inf tensor (input, optional)
//   - foundInf: Tensor indicating presence of inf or nan in gradients. If true, skips operation and step update. (input, optional)
//
// Wraps miopenTransformersAdamWWithOutput.
func (h Handle) TransformersAdamWWithOutput(paramInDesc TensorDescriptor, paramIn uintptr, paramOutDesc TensorDescriptor, paramOut uintptr, paramOutFloat16Desc TensorDescriptor, paramOutFloat16 uintptr, gradInDesc TensorDescriptor, gradIn uintptr, expAvgInDesc TensorDescriptor, expAvgIn uintptr, expAvgOutDesc TensorDescriptor, expAvgOut uintptr, expAvgSqInDesc TensorDescriptor, expAvgSqIn uintptr, expAvgSqOutDesc TensorDescriptor, expAvgSqOut uintptr, stateStepInDesc TensorDescriptor, stateStepIn uintptr, stateStepOutDesc TensorDescriptor, stateStepOut uintptr, stateStep uint32, lr float32, beta1 float32, beta2 float32, weightDecay float32, eps float32, stepSize float32, correctBias bool, gradScaleDesc TensorDescriptor, gradScale uintptr, foundInfDesc TensorDescriptor, foundInf uintptr) error {
	return TransformersAdamWWithOutput(h, paramInDesc, paramIn, paramOutDesc, paramOut, paramOutFloat16Desc, paramOutFloat16, gradInDesc, gradIn, expAvgInDesc, expAvgIn, expAvgOutDesc, expAvgOut, expAvgSqInDesc, expAvgSqIn, expAvgSqOutDesc, expAvgSqOut, stateStepInDesc, stateStepIn, stateStepOutDesc, stateStepOut, stateStep, lr, beta1, beta2, weightDecay, eps, stepSize, correctBias, gradScaleDesc, gradScale, foundInfDesc, foundInf)
}
